from math import gcd
from functools import reduce

def solve(inputs: dict) -> float:
    values = [int(v) for v in inputs['VALUES']]
    result = reduce(gcd, values)
    return float(result)

scripts.lcg:
def solve(inputs: dict) -> float:
    s = inputs['SEED']
    a = inputs['A']
    b = inputs['B']
    m = inputs['M']
    k = int(inputs['K'])
    for _ in range(k):
        s = (a * s + b) % m
    return float(s)

scripts.inversions:
def solve(inputs: dict) -> float:
    values = [int(v) for v in inputs['VALUES']]
    count = 0
    n = len(values)
    for i in range(n):
        for j in range(i+1, n):
            if values[i] > values[j]:
                count += 1
    return float(count)

scripts.factorial_mod:
def solve(inputs: dict) -> float:
    n = int(inputs['N'])
    mod = int(inputs['MOD'])
    result = 1
    for i in range(1, n+1):
        result = (result * i) % mod
    return float(result)

